  --confirm-shadow: 0 18px 48px rgba(40, 36, 30, 0.18);

  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: var(--confirm-scrim);
