}

[data-theme="night"] .myelin-confirm-backdrop {
  --confirm-scrim: rgba(4, 6, 12, 0.6);
  --confirm-surface: #1c2129;
  --confirm-border: #2c333d;
  --confirm-text: #e6e9ee;
