  --confirm-cancel-bg: transparent;
  --confirm-cancel-text: #cdd3dc;
  --confirm-cancel-border: #3a424e;
  --confirm-cancel-hover: #262c36;
  --confirm-danger-bg: #c46a5c;
  --confirm-danger-text: #1a1210;
  --confirm-danger-hover: #d37d70;
  --confirm-focus: #b9c7d9;
  --confirm-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
}

.myelin-confirm {
  width: min(420px, 100%);
  padding: 28px 28px 24px;
  border: 1px solid var(--confirm-border);
  border-radius: 16px;
  background: var(--confirm-surface);
  color: var(--confirm-text);
  box-shadow: var(--confirm-shadow);
  font-family: inherit;
  animation: myelin-confirm-rise 200ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.myelin-confirm__title {
  margin: 0 0 10px;
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1.3;
}

.myelin-confirm__body {
  margin: 0 0 24px;
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--confirm-muted);
  overflow-wrap: anywhere;
}

.myelin-confirm__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.myelin-confirm__button {
  min-width: 96px;
  padding: 10px 18px;
  border-radius: 10px;
  border: 1px solid transparent;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.myelin-confirm__button--cancel {
  background: var(--confirm-cancel-bg);
  color: var(--confirm-cancel-text);
  border-color: var(--confirm-cancel-border);
}

.myelin-confirm__button--cancel:hover {
  background: var(--confirm-cancel-hover);
}

.myelin-confirm__button--danger {
  background: var(--confirm-danger-bg);
  color: var(--confirm-danger-text);
}

.myelin-confirm__button--danger:hover {
  background: var(--confirm-danger-hover);
}

.myelin-confirm__button:focus {
  outline: none;
}

.myelin-confirm__button:focus-visible {
  outline: 2px solid var(--confirm-focus);
  outline-offset: 3px;
}

.myelin-confirm__button:active {
  transform: translateY(1px);
}

@keyframes myelin-confirm-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes myelin-confirm-rise {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .myelin-confirm-backdrop,
  .myelin-confirm,
  .myelin-confirm__button {
    animation: none;
    transition: none;
  }
}
